50	/// A one-hot-ish logits row: a single peak above a flat floor.
51	fn peak_row(vocab: usize, peak: usize, height: f32) -> Vec<f32> {
52	    let mut r = vec![0.0; vocab];
53	    r[peak] = height;
54	    r
55	}
