142	#[test]
143	fn tiny_top_p_routes_to_argmax_even_under_bf16_ties() {
144	    // Regression for the per-step-philox migration (no per-request RNG). A tiny
145	    // top_p must collapse to the same token greedy picks. The hard case is a
146	    // bf16 tie at the top: argmax breaks it by lowest index, but the rejection
147	    // sampler would pick either tied token depending on the seed (the old
148	    // per-request seed masked this; a per-step seed exposes it). Because the
149	    // softmax max is always >= 1/vocab, top_p <= 1/vocab makes the nucleus a
150	    // single token, so the row routes to the deterministic argmax path and
151	    // matches greedy for every seed. Large vocab matches the model's
152	    // OnlineSoftmax regime.
153	    let ctx = DeviceContext::new().unwrap();
154	    let vocab = 151_936;
155	    let lo = 879usize;
156	    let hi = 6941usize;
157	    let mut row = vec![0.0f32; vocab];
158	    row[lo] = 8.0; // bf16-exact, identical to `hi` -> a true top tie
159	    row[hi] = 8.0;
160	    let arena = make_arena(&ctx, &[row]);
161	    let mut scratch = SampleScratch::new(&ctx, vocab, 1).unwrap();
162	
163	    let greedy_tok = select_batch(&ctx, &arena, &[&greedy()], &[0], 0, &mut scratch).unwrap();
164	    assert_eq!(
165	        greedy_tok,
166	        vec![lo as u32],
167	        "argmax breaks the tie by lowest index"
168	    );
169	
170	    let tiny = sampling(1.0, -1, 1e-6); // 1e-6 < 1/vocab (~6.6e-6)
171	    for s in 0..64u64 {
172	        assert_eq!(
173	            select_batch(&ctx, &arena, &[&tiny], &[0], s, &mut scratch).unwrap(),
174	            greedy_tok,
175	            "seed {s}: tiny top_p must match greedy, not sample the tied peer"
176	        );
177	    }
178	}
