221	#[test]
222	fn batch_larger_than_scratch_is_rejected() {
223	    let ctx = DeviceContext::new().unwrap();
224	    let vocab = 8;
225	    let arena = make_arena(&ctx, &[peak_row(vocab, 1, 5.0), peak_row(vocab, 2, 5.0)]);
226	    let params = vec![greedy(); 2];
227	    let mut scratch = SampleScratch::new(&ctx, vocab, 1).unwrap();
